-- Phase 2 (docs/prd.md §5). Backs login, saved home airport, and is the parent
-- for alert_subscriptions/subscriptions in Phase 3.
--
-- id is intentionally not generated by a default tied to an auth schema: when
-- paired with Supabase Auth (docs/architecture.md §7), this id is expected to
-- equal auth.users.id, set by application code at signup, not generated
-- independently here.
create table users (
  id uuid primary key default gen_random_uuid(),
  email text not null,
  home_airport_code text references airports(code) on delete set null,
  created_at timestamptz not null default now()
);

-- Case-insensitive uniqueness as a functional index rather than a plain unique
-- constraint, so "user@x.com" and "User@x.com" can't both sign up.
create unique index idx_users_email_lower on users (lower(email));

create index idx_users_home_airport on users (home_airport_code);
